import numpy as np
class Transformation:
    """Invertible robust per-channel normalization (median/IQR) for forecasting inputs."""
    def fit(self, X, metadata):
        X = np.asarray(X, dtype=float)
        center = np.median(X, axis=0)
        q1, q3 = np.percentile(X, 25, axis=0), np.percentile(X, 75, axis=0)
        scale = np.where((q3 - q1) > 1e-8, (q3 - q1), 1.0)
        return {"center": center, "scale": scale}
    def transform(self, X, state):
        X = np.asarray(X, dtype=float)
        return (X - state["center"]) / state["scale"]
    def inverse_transform(self, Y, state):
        Y = np.asarray(Y, dtype=float)
        return Y * state["scale"] + state["center"]
